        description: "Grande, 3d10+7 de dano ácido plus Podridão do Pântano, Ruptura 28nA criatura tenta engolir um alvo do tamanho listado ou menor que esteja agarrado ou imobilizado nas mandíbulas ou na boca. Se o alvo engolido for do tamanho máximo listado, não pode usar Engolir Inteiro de novo. Se for menor, em geral pode engolir mais; o Mestre define o máximo. A criatura faz um teste de Atletismo contra a CD de Reflexos do alvo. Se passar, engole. A boca ou as mandíbulas deixam de Agarrar quem foi engolido, então a criatura pode usá-las de novo para Golpear ou Agarrar. Não pode atacar alvos que tenha engolido.\nUm alvo engolido fica agarrado, Atrasado 1, e precisa prender a respiração ou começa a sufocar. Sofre o dano listado ao ser engolido e no fim de cada turno enquanto estiver engolido. Se Escapar da condição de agarrado desta habilidade, sai pela boca — isso também solta qualquer outro alvo preso na boca ou nas mandíbulas. Quem está engolido só pode atacar a criatura com ataques desarmados ou armas de Bulk leve ou menor. A criatura que engoliu fica Desprotegida contra esse ataque. Se a criatura sofrer dano perfurante ou cortante igual ou maior que o valor de Ruptura listado num único ataque ou magia, o alvo se corta para fora. Quem se solta (Escapando ou se cortando) pode respirar na hora e sai no espaço da criatura.\nSe a criatura morrer, um alvo engolido pode ser libertado por criaturas adjacentes ao cadáver se gastarem um total combinado de 3 ações cortando-a com arma ou ataque desarmado que cause dano perfurante ou cortante.",
