        id: "time-dragon-adult-temporal-eddies",
        name: "Redemoinhos Temporais",
        originalName: "Temporal Eddies",
        actionType: "two",
        frequency: "once per 10 minutes",
        description: "O dragão Avança ou Voa até seu Deslocamento, deixando imagens residuais de suas versões passadas e futuras em cada espaço pelo qual passa. Até o fim do próximo turno do dragão, ele pode usar qualquer um desses espaços como origem de seus Golpes, magias e outras habilidades. Os observadores também percebem o dragão em todos esses espaços simultaneamente e devem obter sucesso em um teste simples CD 15 para escolhê-lo como alvo; em caso de falha, não o afetam. Uma criatura pode usar uma ação com o traço concentração para tentar identificar a localização verdadeira do dragão, obtendo sucesso em uma salvaguarda de Vontade CD 34.",
