        actionType: "two",
        description: "O dragão exala uma rajada de temporal energy, warping time in a cone de 18 m. criaturas in the area deve tentar uma salvaguarda de Vontade CD 36. O dragão não pode usar Sopro de Deslocamento Temporal de novo por 1d4 rodadas. Sucesso crítico a criatura is unaffected. Sucesso a criatura is Atrasado 1 por 1 rodada. Falha a criatura is Atrasado 2 por 1 rodada. Falha crítica a criatura shifts briefly forward in time, vanishing and reappearing at the beginning of the time dragon's next turn in the same location (or an adjacent space if seu former location is occupied), unaware that any time has passed. While timeshifted, time pauses for that criatura, and it cannot sofrem actions or be affected by anything else.",
