        description: "O dragão vorpal mergulha sobre o campo de batalha, varrendo os inimigos com sua cauda em forma de lâmina de machado. O dragão Voa duas vezes; a qualquer momento durante esse movimento, ele realiza até dois Golpes de lâmina do queixo, cada um contra uma criatura diferente ao alcance. A penalidade de ataques múltiplos do dragão não aumenta até que todos os Golpes sejam realizados.",
