        id: "vorpal-dragon-adult-vorpal-binding",
        name: "Vínculo Vorpal",
        originalName: "Vorpal Binding",
        actionType: "passive",
        description: "O dragão vorpal decapita seus adversários — às vezes sem matá-los. Os Golpes de lâmina do queixo de um dragão vorpal contam como se tivessem a runa de propriedade vorpal para fins de fraquezas. Sempre que o dragão vorpal obtém sucesso crítico em um Golpe de lâmina do queixo, ele causa 3d6 de dano persistente de sangramento adicional, que pode ser encerrado normalmente.\nQuando um dragão vorpal obtém um 20 natural em um Golpe de lâmina do queixo, o alvo deve tentar uma salvaguarda de Fortitude CD 33; este efeito possui o traço incapacitação. Em falha, a criatura é decapitada. Uma criatura decapitada dessa forma não morre automaticamente; em vez disso, sua cabeça e seu corpo continuam vivos, separados mas misticamente ligados, com a cabeça controlando o corpo à distância. A criatura decapitada fica Desajeitada 2 ao tentar coordenar seus movimentos a partir de uma perspectiva incomum, ou Desajeitada 4 se a cabeça não puder perceber o corpo de onde está. Essas condições ficam suprimidas se o corpo segurar a própria cabeça e não se aplicam a ações realizadas exclusivamente pela cabeça, mente ou voz. Se o corpo for morto, a cabeça pode continuar viva, mas destruir a cabeça também mata o corpo. Este efeito pode ser revertido com uma atividade de 2 ações que possui o traço manuseio para recolocar firmemente a cabeça decepada no corpo correto. Fica a critério do MJ decidir se prender a cabeça decepada a outro corpo sem cabeça funciona.",
