        description: "Um dragão de pântano pode realizar um ritual especial sobre o corpo de um humanoide morto pela Podridão do Pântano para erguê-lo como morto-vivo inteligente humanoide.\nThis functions like a 8th-rank ritual, except that it sofre only 8 hours, the bog dragon doesn't require any secondary casters, e don't need to pay a cost.\nSe o dragão de pântano falha criticamente no teste de perícia do ritual, obtém uma falha em vez disso.",
