        description: "Um jorro de sangue espirra da ferida do dragão e se calcifica instantaneamente em um ramo serrilhado de coral afiado. O ramo de coral empala a criatura que disparou a reação, causando 10d6 de dano perfurante (Reflexos CD 44). Em uma falha crítica, a criatura também sofre 1d4 de dano persistente de sangramento. Independentemente do resultado, o coral então se desfaz em pó.",
