        name: "Chamariz de Língua",
        originalName: "Tongue Decoy",
        actionType: "passive",
        description: "O dragão do desespero infla várias bolsas na ponta da língua para criar a forma básica de uma criatura. Esse processo leva 1 minuto para ser concluído, durante o qual o dragão fica Desprotegido. Se o dragão parar ou for interrompido durante o processo, as bolsas esvaziam, e ele deve recomeçar. Quando o processo termina, o dragão pode manter as bolsas infladas indefinidamente e pode Dissipar para esvaziá-las e retrair a língua instantaneamente.\nA língua inflada assume a forma básica de um animal ou humanoide e pode ser inflada para ficar Pequena ou Média. A forma lembra a silhueta geral de uma criatura, embora uma inspeção mais atenta e um sucesso em um teste de Percepção CD 30 possam revelar a verdadeira natureza da língua. Enquanto ela estiver inflada, o dragão pode projetar sua voz através do chamariz, embora manter a língua inflada dificulte a fala, fazendo-o sofrer –4 de penalidade de circunstância em testes relacionados à fala, como testes de Dissimulação para Mentir.\nA língua do dragão pode se estender até 27 m de seu corpo, e ele pode estendê-la completamente como parte do processo de inflar as bolsas. O dragão pode mover a parte inflada da língua até 4,5 m por vez com uma ação que possui os traços concentração, manuseio e movimento. Enquanto estiver estendida, a ponta inflada da língua ocupa espaço como uma criatura do tamanho apropriado, mas o restante da língua não impede nem bloqueia o movimento de qualquer forma. O faro do dragão funciona por meio de cílios na ponta da língua, mas, fora isso, ele não tem como saber o que está perto dela.\nAtacar a língua é o mesmo que atacar o dragão, exceto que a língua está sempre Desprotegida. Se a língua sofrer qualquer dano, ela esvazia imediatamente e permanece estendida. O dragão fica Desprotegido enquanto sua língua estiver estendida, mas pode retraí-la com duas ações consecutivas de Interagir. Se a língua sofrer dano, o dragão não pode usar Chamariz de Língua de novo por 1 dia.",
