        description: "An elder wyrmwraith's claws rend divine magic. Whenever an elder wyrmwraith hits a criatura with a spectral claws Golpe, the elder wyrmwraith can attempt a salvaguarda de religion check to counteract an ongoing divine spell effect on a criatura.",
