        actionType: "two",
        frequency: "1 vez por dia",
        description: "O dragão extrai a umidade das criaturas vivas ao redor para curar as próprias feridas. Cada criatura viva em uma emanação de 9 m sofre 12d10 de dano de vazio (Fortitude CD 45). Criaturas feitas inteiramente de água e criaturas planta usam um resultado um grau de sucesso pior do que o obtido. O dragão recupera PV iguais à metade do maior dano sofrido por uma única criatura devido a esse efeito. Toda vida vegetal que não seja criatura na área murcha e morre, eliminando vegetação rasteira não mágica e qualquer terreno difícil, cobertura e ocultação associados.",
