        description: "O dragão vorpal decapita seus inimigos — às vezes sem matá-los. Os Golpes de lâmina do queixo de um dragão vorpal contam como se tivessem a runa de propriedade de arma vorpal para fins de fraquezas. Sempre que o dragão vorpal obtém sucesso crítico em um Golpe de lâmina do queixo, ele causa 6d6 de dano persistente de sangramento adicional, que pode ser encerrado normalmente. Quando um dragão vorpal obtém um 20 natural em um Golpe de lâmina do queixo, o alvo deve tentar uma salvaguarda de Fortitude CD 44; esse efeito possui o traço incapacitação. Em uma falha, a criatura é decapitada. Uma criatura decapitada dessa forma não morre automaticamente; em vez disso, sua cabeça e seu corpo continuam vivos, separados, mas ligados misticamente, com a cabeça controlando o corpo à distância. Uma criatura decapitada fica Desajeitada 2 enquanto tenta coordenar seus movimentos a partir de uma perspectiva incomum, ou Desajeitada 4 se sua cabeça não puder perceber o corpo a partir de onde está. Essas condições são suprimidas se o corpo segurar a própria cabeça e não se aplicam a ações realizadas exclusivamente pela cabeça, mente ou voz. Se o corpo morrer, a cabeça pode continuar viva, mas destruir a cabeça também mata o corpo. Esse efeito só pode ser encerrado por um efeito capaz de restaurar os mortos à vida; contudo, apenas efeitos que restaurem um cadáver incompleto substituem um corpo ausente ou destruído. O dragão pode escolher matar instantaneamente uma criatura ao decapitá-la, conforme a ativação da runa de propriedade de arma vorpal.",
