        name: "Sopro Fétido",
        originalName: "Nidorous Breath",
        actionType: "two",
        description: "O dragão vomita um jato fervente de ácido estomacal fermentado que causa 6d8 de dano ácido num cone de 9 m (Reflexos CD 25). Não pode usar Sopro Fétido de novo por 1d4 rodadas.",
