        description: "27 m. Uma criatura que enters or começa o turno in the area deve tentar uma salvaguarda de Vontade CD 23. independentemente do resultado of the salvaguarda, a criatura is imune temporariamente to the graceless domain aura por 1 minuto. O dragão can exclude criaturas from this aura. Sucesso crítico a criatura is unaffected. Sucesso For 1 rodada, the first time a criatura rolls an Athletics, Acrobatics, or Performance skill check, it rola duas vezes e fica com o pior resultado. Falha For 1 minuto, the first time each rodada a criatura rolls an Athletics, Acrobatics, or Performance skill check, it rola duas vezes e fica com o pior resultado. Falha crítica For 1 minuto, every time a criatura rolls an Athletics, Acrobatics, or Performance skill check, it rola duas vezes e fica com o pior resultado.",
